query OrdersByEmail($search: String!, $first: Int!) {
    orders(first: $first, sortKey: CREATED_AT, reverse: true, query: $search) {
        nodes {
            id
            customer {
                id
                displayName
            }
            confirmationNumber
            statusPageUrl
            createdAt
            email
            name
            note
            tags
            updatedAt
            cancelReason
            currentSubtotalPriceSet {
                shopMoney {
                    amount
                    currencyCode
                }
                presentmentMoney {
                    amount
                    currencyCode
                }
            }
            currentTotalDiscountsSet {
                shopMoney {
                    amount
                    currencyCode
                }
                presentmentMoney {
                    amount
                    currencyCode
                }
            }
            currentTotalTaxSet {
                shopMoney {
                    amount
                    currencyCode
                }
                presentmentMoney {
                    amount
                    currencyCode
                }
            }
            currentTotalPriceSet {
                shopMoney {
                    amount
                    currencyCode
                }
                presentmentMoney {
                    amount
                    currencyCode
                }
            }
            displayFinancialStatus
            displayFulfillmentStatus
            shippingAddress {
                address1
                address2
                city
                province
                provinceCode
                zip
                country
                countryCodeV2
            }
            shippingLines(first: 40) {
                nodes {
                    title
                }
            }
            lineItems(first: 40) {
                nodes {
                    id
                    name
                    sku
                    vendor
                    isGiftCard
                    quantity
                    variant {
                        id
                        title
                    }
                    product {
                        id
                        title
                    }
                    originalUnitPriceSet {
                        shopMoney {
                            amount
                            currencyCode
                        }
                    }
                    totalDiscountSet {
                        shopMoney {
                            amount
                        }
                    }
                }
            }
        }
    }
}
